 return `<article class="program-row ${index%2===0?'tinted':''}${mine?(priority.backup?' priority-backup':' priority-primary'):''}" data-report-id="${esc(r.id)}"><div class="time-column ${poster?'poster-column':''}"><div class="time-slot">${number?`<div class="row-number">${esc(number)}</div>`:''}${!poster?timing:''}</div></div><div class="report-content"><div class="report-main">${!poster?`<div class="type-label">${esc(type(r))}${mine&&primaryConflicts.has(r.id)?'<span class="row-conflict">时间重叠</span>':''}</div>`:''}<button type="button" class="report-title" data-detail="${esc(r.id)}">${esc(r.title)}</button>${r.timeUncertain?'<p class="conflict">原表时间待核对</p>':''}${r.audience?`<p class="audience">${esc(r.audience)}</p>`:''}${person}${mine?`<div class="row-location">${esc(M.venueLabel(r))} · ${esc(room(r.room)||'原表未注明展示地点')}</div>`:''}</div>${mine?'<div class="report-actions">':''}<button type="button" class="star" data-star="${esc(r.id)}" aria-label="${saved?'取消收藏':'收藏'} ${esc(r.number||r.title)}" aria-pressed="${saved}">${saved?'★':'☆'}</button>${mine&&priority.adjustable?`<button type="button" class="row-priority ${priority.backup?'is-backup':''}" data-priority-id="${esc(r.id)}" data-priority="${priority.backup?'primary':'backup'}" aria-label="${esc(r.number||r.title)}：当前${priority.backup?'备选，改为首选':'首选，改为备选'}" title="点击改为${priority.backup?'首选':'备选'}">${priority.backup?'备选':'首选'}</button>`:''}${mine?'</div>':''}</div></article>`;
