function scrollToResults(){const top=$('app').getBoundingClientRect().top+window.scrollY;window.scrollTo({top:Math.max(0,top),behavior:'auto'});}
function changeFilter(values){Object.assign(states[view],values);render();navigation.replace();}
$('kind-tabs').addEventListener('click',e=>{const t=e.target.closest('[data-kind]');if(!t)return;if(view==='mine'){const filter=M.mineFilter(t.dataset.kind);priorityFilter=filter.priority;changeFilter({kind:filter.kind});}else changeFilter({kind:t.dataset.kind,date:''});});
$('date-tabs').addEventListener('click',e=>{const t=e.target.closest('[data-date]');if(t)changeFilter({date:t.dataset.date});});
$('track').addEventListener('change',e=>{ $('track-info').open=true;changeFilter({track:e.target.value});});
function search(){if(!composing){clearTimeout(searchTimer);searchTimer=setTimeout(()=>changeFilter({query:$('search').value}),100);}}
$('search').addEventListener('input',search);$('search').addEventListener('compositionstart',()=>composing=true);$('search').addEventListener('compositionend',()=>{composing=false;search();});
$('clear').addEventListener('click',()=>{clearTimeout(searchTimer);changeFilter({query:''});});
$('search-toggle').addEventListener('click',()=>{searchOpen=!searchOpen;render();if(searchOpen)$('search').focus();else $('search').blur();navigation.replace();});
function moveDay(step){const next=visibleDates[visibleDates.indexOf(states[view].date)+step];if(next){changeFilter({date:next});scrollToResults();}}
$('previous').addEventListener('click',()=>moveDay(-1));$('next').addEventListener('click',()=>moveDay(1));
function rememberCurrent(){const snapshot=captureScreen();snapshot.detail='';if(M.area(view)==='branch')lastBranch=snapshot;else if(M.area(view)==='program')lastProgram=snapshot;}
function openView(name,track){pendingPosition=null;clearTimeout(searchTimer);if(view===name&&!detailId&&(track===undefined||track===states[name]?.track))return;rememberCurrent();navigation.navigate(()=>{hideDetail();searchOpen=false;view=name;if(['agenda','program'].includes(name)&&track!==undefined)Object.assign(states[name],{kind:'oral',date:'',track,query:''});$('track-info').open=true;render();scrollToResults();});}
function resumeSection(snapshot){rememberCurrent();const target=M.area(snapshot.view),restored=Object.assign({},snapshot,{agenda:target==='branch'?snapshot.agenda:{...states.agenda},program:target==='program'?snapshot.program:{...states.program},mine:{...states.mine},lastBranch,lastProgram});navigation.navigate(()=>restoreNavigation(restored));}
$('tab-mine').addEventListener('click',()=>openView('mine'));
$('tab-home').addEventListener('click',()=>{if(M.area(view)!=='branch'&&lastBranch)resumeSection(lastBranch);else openView('home');});
$('tab-program').addEventListener('click',()=>{if(M.area(view)!=='program'&&lastProgram)resumeSection(lastProgram);else openView('program-home');});
$('program-home-view').addEventListener('click',e=>{const target=e.target.closest('[data-program]');if(target&&programById.has(target.dataset.program))openView('program',target.dataset.program);});
